import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ChatInputProps = Record<string, any>;

const ChatInput: React.FC<ChatInputProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 6,
  inputText = "Write a poem about the ocean using only 3 lines...",
  placeholderText = "Send a message...",
  boxColor = "#40414F",
  textColor = "#FFFFFF",
  sendButtonColor = "#19C37D",
  boxWidthPercent = 80,
  fontSize = 24,
}) => {
  
  // Load standard UI font
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color logic
  const bg = transparentBackground ? "transparent" : backgroundColor;

  // Animation configuration
  const startDelay = 15; // Frames before typing starts
  const typingDuration = fps * (durationInSeconds * 0.5); // Typing takes up 50% of duration
  const fadeDuration = 20;

  // 1. Entrance Spring (Scale & Opacity of the box)
  const entrance = spring({
    frame,
    fps,
    config: { damping: 12 },
  });

  // 2. Typing Logic
  const progress = interpolate(
    frame,
    [startDelay, startDelay + typingDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const charCount = Math.round(progress * inputText.length);
  const currentText = inputText.slice(0, charCount);

  // 4. Send Button Activation
  // Becomes active/visible when typing starts, maybe highlight when done
  const isTypingDone = progress >= 1;
  const sendButtonOpacity = interpolate(
    frame,
    [startDelay, startDelay + 10],
    [0.3, 1], // Starts dim, becomes fully visible
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const sendButtonScale = spring({
    frame: frame - (startDelay + typingDuration),
    fps,
    config: { stiffness: 200, damping: 10 },
  });
  
  const finalSendScale = isTypingDone ? 1 + (sendButtonScale * 0.1) : 1; 
  const currentSendColor = isTypingDone ? sendButtonColor : "#8e8ea0";

  // Layout Constants
  const boxWidth = width * (boxWidthPercent / 100);
  const boxHeight = 80; // Fixed height for single line representation, or grow if needed. 
  // For simplicity in this animation, we'll keep a fixed height resembling a standard prompt bar.
  
  const padding = 24;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bg,
        fontFamily: "Inter",
        justifyContent: "center", // Changed from flex-start to center
        alignItems: "center",
      }}
    >
      {/* Input Box Container */}
      <div
        style={{
          width: boxWidth,
          minHeight: boxHeight,
          // Removed marginTop to allow flex centering to work
          backgroundColor: boxColor,
          borderRadius: 12,
          boxShadow: "0 10px 30px rgba(0,0,0,0.3)",
          display: "flex",
          alignItems: "center",
          padding: `${padding}px`,
          gap: padding,
          position: "relative",
          transform: `scale(${entrance})`,
          opacity: interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" }),
        }}
      >
        {/* Text Area Simulation */}
        <div
          style={{
            flex: 1,
            fontSize: fontSize,
            color: textColor,
            fontFamily: "Inter",
            fontWeight: 400,
            lineHeight: 1.5,
            whiteSpace: "pre-wrap",
            display: "flex",
            alignItems: "center",
            height: "100%",
            overflow: "hidden"
          }}
        >
          {/* Placeholder (visible if text is empty) */}
          {currentText.length === 0 && (
             <span style={{ color: "#8e8ea0", position: "absolute" }}>{placeholderText}</span>
          )}
          
          {/* Typed Text */}
          <span>{currentText}</span>
        </div>

        {/* Send Button - "Generate" */}
        <div
          style={{
            padding: "10px 18px",
            borderRadius: 8,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transition: "none",
            opacity: sendButtonOpacity,
            backgroundColor: isTypingDone ? currentSendColor : "transparent",
            border: isTypingDone ? "none" : "1px solid #8e8ea0",
            transform: `scale(${isTypingDone ? 1 : 1})`,
          }}
        >
          <span
            style={{
              fontFamily: "Inter",
              fontSize: 16,
              fontWeight: 500,
              color: isTypingDone ? "#FFFFFF" : "#8e8ea0",
              letterSpacing: 0.2,
            }}
          >
            Generate
          </span>
        </div>
      </div>

      {/* Optional: Avatar or Label above input (mimicking the "You" label) */}
      <div
        style={{
          position: "absolute",
          top: height / 2 - boxHeight - 40,
          left: (width - boxWidth) / 2,
          display: "flex",
          alignItems: "center",
          gap: 12,
          opacity: interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" }),
          transform: `translateY(${interpolate(frame, [0, 20], [20, 0], { extrapolateRight: "clamp" })}px)`
        }}
      >
      </div>

    </AbsoluteFill>
  );
};

export default ChatInput;